int pangkatMod(int a, int b, int m) {
    if (b == 0) {
        return 1 % m;
    }
    int setengah = pangkatMod(a, b / 2, m);
    int hasil = setengah * setengah % m;
    if (b % 2 == 1) {
        hasil = hasil * (a % m) % m;
    }
    return hasil;
}

int main() {
    int a, b, m;
    cin >> a >> b >> m;
    cout << pangkatMod(a, b, m) << endl;
    return 0;
}

