int partisi(int n, int maks) {
    if (n == 0) {
        return 1;
    }
    if (maks == 0) {
        return 0;
    }
    if (maks > n) {
        return partisi(n, n);
    }
    return partisi(n - maks, maks) + partisi(n, maks - 1);
}

int main() {
    int n;
    cin >> n;
    cout << partisi(n, n) << endl;
    return 0;
}

