int catalan(int n) {
    if (n == 0) {
        return 1;
    }
    int jumlah = 0;
    for (int k = 0; k < n; k++) {
        jumlah += catalan(k) * catalan(n - 1 - k);
    }
    return jumlah;
}

int main() {
    int n;
    cin >> n;
    cout << catalan(n) << endl;
    return 0;
}

