void susun(string awalan, string sisa) {
    if (sisa.size() == 0) {
        cout << awalan << endl;
        return;
    }
    for (char c = 'a'; c <= 'z'; c++) {
        int posisi = -1;
        for (int k = 0; k < (int) sisa.size(); k++) {
            if (sisa[k] == c) {
                posisi = k;
            }
        }
        if (posisi >= 0) {
            susun(awalan + c, sisa.substr(0, posisi) + sisa.substr(posisi + 1));
        }
    }
}

int main() {
    string kata;
    cin >> kata;
    susun("", kata);
    return 0;
}

