void buat(string sejauhIni, int buka, int tutup, int n) {
    if (buka == n && tutup == n) {
        cout << sejauhIni << endl;
        return;
    }
    if (buka < n) {
        buat(sejauhIni + "(", buka + 1, tutup, n);
    }
    if (tutup < buka) {
        buat(sejauhIni + ")", buka, tutup + 1, n);
    }
}

