void baris(int panjang, int tingkat) {
    if (tingkat == 0) {
        for (int k = 0; k < panjang; k++) {
            cout << "#";
        }
        return;
    }
    baris(panjang / 3, tingkat - 1);
    for (int k = 0; k < panjang / 3; k++) {
        cout << " ";
    }
    baris(panjang / 3, tingkat - 1);
}

