    int panjang = 1;
    for (int k = 0; k < n; k++) {
        panjang *= 3;
    }
    for (int tingkat = 0; tingkat <= n; tingkat++) {
        baris(panjang, tingkat);
        cout << endl;
    }
    return 0;
}

